INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(133288, 'ruRU', '', 'Ты тренировался? Великий забег по Гномрегану скоро начнётся!', 24330),
(133289, 'ruRU', '', 'Не забудь пить воду и отдохнуть перед Великим забегом по Гномрегану! Он начнётся в Новом Тинкертауне совсем скоро!', 24330),
(133290, 'ruRU', '', 'Великий забег по Гномрегану проходит в Новом Тинкертауне прямо сейчас! Думаешь, сможешь поставить новый личный рекорд?!', 24330),
(133291, 'ruRU', '', 'Великий забег по Гномрегану проходит прямо сейчас в Новом Тинкертауне!', 24330),
(133292, 'ruRU', '', 'Альянс празднует Великий забег по Гномрегану в Новом Тинкертауне!', 24330),
(133293, 'ruRU', '', 'Альянс проведёт Великий забег по Гномрегану в Новом Тинкертауне совсем скоро!', 24330),
(133482, 'ruRU', '', '|TInterface\\Icons\\INV_MISC_AMMO_ARROW_03:20|t%s целится во врагов |cFFFF0000|Hspell:230139|h[Выстрелом гидры]|h|r!', 24330),
(133767, 'ruRU', '', 'Один из повелителей Легиона наконец падёт, но эта война далека от завершения.\n\nБыл ли это истинный план Саргераса с самого начала? Его окончательная цель? Или, возможно, это дело рук кого-то другого. Кого-то, кто уже предавал этот мир прежде.\n\n<Майев сужает глаза, глядя на небо.>\n\nЯ буду наблюдать... и быть готовой.', 24330),
(134190, 'ruRU', '', 'Хм... похоже, один из наших победителей покинул здание. Это их потеря!', 24330),
(136247, 'ruRU', '', 'Приветствую.', 26972),
(137938, 'ruRU', '', 'Вашрин? Он упоминал что-то о добыче новых предметов и переезде на Виндикар на Аргусе.', 26365),
(141912, 'ruRU', '', 'Тысячи лет Светозарные сражались с демонами в Круговерти Пустоты. Зенедар был единственным домом, который мы знали.', 26972),
(141913, 'ruRU', '', 'Теперь, впервые за долгие века, мы можем идти под небом, не осквернённым безумием Легиона... и снова чувствовать землю под копытами.', 26972),
(141914, 'ruRU', '', 'Но нам нельзя становиться самодовольными. Одна война заканчивается, начинается следующая. Такова жизнь солдата.', 26972),
(141915, 'ruRU', '', 'Твой долг начинается в Штормграде. Исследуй этот мир Азерота. Познакомься с людьми и местами, которые мы клялись защищать.', 26972),
(141916, 'ruRU', '', 'И всегда иди в Свете, $p.', 26972),
(141918, 'ruRU', '', 'Долгие века наш народ называл Расколотые острова своим домом. Мы мало знаем об Азероте, что существует за пределами наших берегов.', 26972),
(141919, 'ruRU', '', 'Пришло время это изменить.', 26972),
(141920, 'ruRU', '', 'Сегодня ты начинаешь новое путешествие, $p. Ты станешь нашим голосом в землях за горой.', 26972),
(141921, 'ruRU', '', 'Иди в Оргриммар. Познакомься с нашими новыми союзниками и узнай, что им важно... за что они сражаются.', 26972),
(141922, 'ruRU', '', 'Оставайся верен себе. И если тебе когда-нибудь будет не хватать дома, знай, что Вершина всегда здесь для тебя.', 26972),
(143276, 'ruRU', '', 'Когда наш город переживал свой самый тёмный час, герои Азерота сражались с нами, чтобы изгнать Легион. Некоторые делали это неохотно.', 26972),
(143277, 'ruRU', '', 'Но синдорай - эльфы крови - проявили к нам уважение и понимание. Их родство доказало, что в Азероте есть и другие, кто разделяет наши ценности.', 26972),
(143288, 'ruRU', '', 'Теперь наш черёд показать силу и честь, которые мы приносим Орде.', 26972),
(143290, 'ruRU', '', '$n, я рад, что ты здесь. Нам нужно убедить вождя заключить союз с ночнорождёнными.', 27404),
(143292, 'ruRU', '', 'Путешествуя по дорогам Азерота, рассказывай встречным о гордой истории ночнорождённых... и покажи им, что мы больше не живём в затворничестве.', 26972),
(143293, 'ruRU', '', 'Иди в Оргриммар. Объединись с нашими союзниками и вместе выкуй новое будущее.', 26972),
(143592, 'ruRU', '', 'Таурены Вершины обладают силой и мужеством. Нам понадобятся такие качества в грядущие дни.', 26972),
(143593, 'ruRU', '', 'У Орды много соперников в этом мире. Одни зовут нас врагами... другие изгнанниками. Но мы находим силу в единстве... и в неповиновении тем, кто посмеет бросить вызов нашей свободе.', 26972),
(143594, 'ruRU', '', 'Будь уверен, я буду следить за твоими успехами. Как вождь, я многого ожидаю от тебя... и я вознаграждаю тех, кто служит мне хорошо.', 26972),
(143595, 'ruRU', '', 'Довольно любезностей. Тебе многое нужно доказать, герой. Куда бы ни вёл тебя путь, знай, что ты сражаешься... за Орду!', 26972),
(143596, 'ruRU', '', 'Ночнорождённые - мудрый и могущественный народ. Древние знания, которыми ты обладаешь, окажутся великим благом для нашего дела.', 26972),
(143712, 'ruRU', '', 'Наконец-то бесконечное позёрство между Ордой и Альянсом подходит к концу.$b$bВремя войны настало.', 27404),
(144396, 'ruRU', '', 'Ночнорождённые по-настоящему свободны. Нам больше не нужен Ночной Колодец, ни его сила.$B$BМы можем выковать собственную судьбу.', 26972),
(144397, 'ruRU', '', 'Дело с Элизандой завершено, но для города ещё многое предстоит сделать.', 26972),
(144621, 'ruRU', '', 'Приветствую, $p! Новые земли и союзники ждут нас по всему Азероту.$B$BОкулет подготовил порталы внизу, когда будешь готов.', 26972),
(144677, 'ruRU', '', 'У меня предчувствие, что наш город скоро понадобится. Я планирую быть готовой, когда придёт время.', 26972),
(144678, 'ruRU', '', '<У Арлюэль отсутствующий взгляд.>$B$BЕсли бы только мой брат мог увидеть город сейчас...', 26972),
(144921, 'ruRU', '', 'Да заберёт Свет этот стол! Возможно, я больше никогда не смогу использовать эту мастерскую.$B$BПорча от тех шкур зверей с Аргуса не проходит, сколько ни отчищай поверхность.', 26972),
(144924, 'ruRU', '', '<Фария приветствует тебя тёплой улыбкой.>$B$BТы хорошо прошёл испытания, $c. Но я чувствую, что твоя история только начинается.', 26972);
